#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long k;
    cin >> n >> k;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    unordered_map<long long, int> first;
    first[0] = -1;
    long long prefix = 0;
    bool found = false;
    for (int i = 0; i < n && !found; i++) {
        prefix += a[i];
        long long rem = prefix % k;
        auto it = first.find(rem);
        if (it != first.end()) {
            if (i - it->second >= 2) found = true;
        } else {
            first[rem] = i;
        }
    }
    cout << (found ? "yes" : "no") << "\n";

    return 0;
}

